      ('grid_fees_and_taxes'::text, null::text, '199.5'::jsonb, 'EUR-PER-MegaW-HR'::text, '2025-01-01'::date, null::date, 'be_eurostat_household_prices'::text, 'nrg_pc_204_c, 2025, band KWH2500-4999, components NETC 0.1196 and TAX_FEE_LEV_CHRG 0.0799 EUR/kWh, VAT excluded; a national mean, the network costs differ by region'::text),
      ('metering_step'::text, 'BE-BRU'::text, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-10-20'::date, null::date, 'be_sibelga_consumption_history'::text, 'Section on the consumption history: a smart meter or a remote meter transmits data every quarter of an hour; a mechanical meter gives annual consumption only'::text),
      ('metering_step'::text, 'BE-VLG'::text, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-10-20'::date, null::date, 'be_fluvius_quarter_hour'::text, 'Page text: the digital electricity meter measures consumption per quarter hour; an electricity meter that is not digital gives index readings only'::text),
      ('metering_step'::text, 'BE-WAL'::text, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2026-10-20'::date, null::date, 'be_ores_smart_meter'::text, 'Page text: the communicating meter collects consumption by intervals of 15 minutes; a meter that is not communicating gives index readings only'::text),
      ('vat_rate_electricity'::text, null::text, '0.06'::jsonb, 'UNITLESS'::text, '2023-04-01'::date, null::date, 'be_fps_finance_energy_bill'::text, 'From 1 April 2023 the VAT rate on natural gas and electricity is permanently 6 % instead of 21 %, for a private customer'::text)
  ),
  problems (problem) as (
    select format('property_unknown: %s is not a property_defs code', p.property_code)
      from pack p
     where not exists (select 1 from property_defs d where d.code = p.property_code)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.property_code, q.unit, p.unit)
      from pack p
      join property_defs d on d.code = p.property_code
      join quantities q on q.code = d.quantity_code
     where q.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.property_code, coalesce(' (' || p.region || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'BE' and x.property_code = p.property_code
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (property_code, country, region, value, valid_from, valid_to, source_code, reference, published_by)
    select p.property_code, 'BE', p.region, p.value, p.valid_from, p.valid_to, p.source_code, p.reference, 'pack:be'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, property_code, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
